tent": [{"type": "paragraph", "content": [{"type": "text", "text": "概率范围验证遗漏"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "基础概率的核心是\"等可能事件的计数\"。先确定总数和目标数再算概率。"}]}]}]}$$ AS jsonb), NULL, '数量关系-概率问题-基础概率的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "概率问题", "基础概率"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_prob_basic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
